def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    coordinates = sorted({x for op in ops for x in (op[1], op[2] + 1)})
    index = {x: i for i, x in enumerate(coordinates)}
    size = len(coordinates) - 1
    infinity = 10**10

    minimum = [0] * (4 * size)
    second = [infinity] * (4 * size)

    def push(node: int) -> None:
        left = node * 2
        right = left + 1
        value = minimum[node]

        if second[node] == infinity:
            minimum[left] = minimum[right] = value
            second[left] = second[right] = infinity
        else:
            if minimum[left] < value:
                minimum[left] = value
            if minimum[right] < value:
                minimum[right] = value

    def pull(node: int) -> None:
        left = node * 2
        right = left + 1
        a = minimum[left]
        b = minimum[right]

        if a < b:
            minimum[node] = a
            second[node] = min(second[left], b)
        elif b < a:
            minimum[node] = b
            second[node] = min(a, second[right])
        else:
            minimum[node] = a
            second[node] = min(second[left], second[right])

    def update(
        node: int, lo: int, hi: int, ql: int, qr: int, colour: int
    ) -> None:
        if colour != 0 and minimum[node] >= colour:
            return

        if ql <= lo and hi <= qr:
            if colour == 0:
                minimum[node] = 0
                second[node] = infinity
                return
            if colour < second[node]:
                minimum[node] = colour
                return

        push(node)
        mid = (lo + hi) // 2
        if ql < mid:
            update(node * 2, lo, mid, ql, qr, colour)
        if qr > mid:
            update(node * 2 + 1, mid, hi, ql, qr, colour)
        pull(node)

    for op in ops:
        left = index[op[1]]
        right = index[op[2] + 1]
        colour = op[3] if op[0] == 1 else 0
        update(1, 0, size, left, right, colour)

    counts = {}

    def collect(node: int, lo: int, hi: int) -> None:
        if second[node] == infinity:
            colour = minimum[node]
            if colour:
                counts[colour] = counts.get(colour, 0) + coordinates[hi] - coordinates[lo]
            return

        push(node)
        mid = (lo + hi) // 2
        collect(node * 2, lo, mid)
        collect(node * 2 + 1, mid, hi)

    collect(1, 0, size)
    return [[colour, counts[colour]] for colour in sorted(counts)]
